$$
\begin{aligned}\int \frac{1}{(x+3)\sqrt{-{x}^{2}-6x}}\text{d}x & =\int \frac{1}{(x+3)\sqrt{9-(x+3)^{2}}}\,\text{d}x \\  & =\int \frac{1}{3(x+3)\sqrt{1-{\left(\frac{x+3}{3}\right)}^{2}}}\,\text{d}x \\  & =\frac{1}{9}\int \frac{1}{\left(\frac{x+3}{3}\right)\sqrt{1-{\left(\frac{x+3}{3}\right)}^{2}}}\,\text{d}x.\end{aligned}
